const client = new RoomClient();
const statusLabels:Record<string,string>={queued:'排队中',running:'工作中',waiting_input:'等待输入',cancel_requested:'正在停止',completed:'已完成',failed:'未完成',canceled:'已取消',superseded:'已被新目标替代',interrupted:'已中断',unknown:'状态待核实',proposed:'待你确认'};
const roomToolLabels:Record<string,string>={room_read:'读取房间',room_status:'房间状态',room_inbox:'增量读取',room_post:'发言',task_propose:'提议任务',task_claim:'领取任务',task_context:'核对任务上下文',task_complete:'完成任务',task_heartbeat:'任务心跳',artifact_publish:'发布交付物'};
const providerLabels:Record<string,string>={codex:'Codex App Server',claude:'Claude Code CLI',deepseek:'DeepSeek Harness · ACP',api:'自建模型 API',a2a:'A2A 1.0',demo:'确定性演示'};
const marks:Record<string,string>={codex:'Cx',claude:'Cl',deepseek:'Ds',api:'Ai',a2a:'A2',demo:'De'};
function Icon({name,size=18}:{name:string;size?:number}) {
 const paths:Record<string,React.ReactNode>={
  chat:<><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H5l-3 3v-9.5A7.5 7.5 0 0 1 9.5 5h3A7.5 7.5 0 0 1 20 11.5Z"/><path d="M7 10h8M7 14h5"/></>,
  plus:<path d="M12 5v14M5 12h14"/>,send:<><path d="m5 12 7-7 7 7M12 5v15"/></>,
  attach:<path d="m8 13 6-6a3 3 0 0 1 4 4l-8 8a5 5 0 0 1-7-7l8-8"/>,
  settings:<><path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/></>,
  arrow:<path d="m8 5 7 7-7 7"/>,check:<path d="m5 12 4 4L19 6"/>,close:<path d="m6 6 12 12M6 18 18 6"/>,
  task:<><rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h3"/></>,
  file:<><path d="M14 2H5v20h14V7Z"/><path d="M14 2v5h5M8 12h8M8 16h6"/></>,
  shield:<><path d="m12 3 8 3v6c0 4-5 8-8 9-3-1-8-5-8-9V6Z"/><path d="m8 12 3 3 5-6"/></>,
  play:<path d="m8 5 11 7-11 7Z"/>,stop:<rect x="6" y="6" width="12" height="12" rx="2"/>,
  reply:<><path d="m8 5-5 5 5 5M3 10h9a7 7 0 0 1 7 7v3"/></>,
  download:<><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/></>,
  grid:<><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,
  list:<><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></>
 };
 return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]??paths.chat}</svg>;
}
function Avatar({agent,human=false}:{agent?:AgentDescriptor;human?:boolean}) {return <span className={`avatar ${human?'human':agent?.color??'system'}`}>{human?'你':agent?marks[agent.provider]:'T'}</span>;}
function Modal({title,subtitle,children,onClose}:{title:string;subtitle?:string;children:React.ReactNode;onClose:()=>void}) {
 const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{ref.current?.showModal();return()=>ref.current?.close();},[]);
 return <dialog ref={ref} className="modal" onCancel={onClose} onClick={e=>{if(e.target===ref.current)onClose();}}><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" aria-label="关闭" onClick={onClose}><Icon name="close"/></button></header>{children}</dialog>;
}
function App(){
 const [ready,setReady]=useState(false),[fatal,setFatal]=useState(''),[rooms,setRooms]=useState<Room[]>([]),[roomId,setRoomId]=useState(''),[snapshot,setSnapshot]=useState<RoomSnapshot>(),[allAgents,setAllAgents]=useState<AgentDescriptor[]>([]);
 const [connected,setConnected]=useState(false),[draft,setDraft]=useState(''),[mentions,setMentions]=useState<string[]>([]),[showMentions,setShowMentions]=useState(false),[reply,setReply]=useState<Message>(),[attachments,setAttachments]=useState<Artifact[]>([]),[busy,setBusy]=useState(false),[notice,setNotice]=useState('');
 const [hasConnected,setHasConnected]=useState(false);
 const [textAction,setTextAction]=useState<{kind:'revise'|'input';id:string;text:string}>();
 const [dialog,setDialog]=useState<'room'|'discussion'|'task'|'agents'|'room-settings'|'execution'|null>(null),[editing,setEditing]=useState<AgentDescriptor>(),[preview,setPreview]=useState<{artifact:Artifact;text:string|null}>(),[rightTab,setRightTab]=useState<'tasks'|'artifacts'|'usage'>('tasks');
 const [settings,setSettings]=useState<ExecutionSettings>();
 const [runDetailId,setRunDetailId]=useState<string>();
 const [discussionDetailId,setDiscussionDetailId]=useState<string>();
 const [helpOpen,setHelpOpen]=useState(false);
 const [mobileDetailsOpen,setMobileDetailsOpen]=useState(false);
 const [roomQuery,setRoomQuery]=useState('');
 const [density,setDensity]=useState<'comfortable'|'compact'>(()=>{try{return localStorage.getItem('temptroom-density')==='compact'?'compact':'comfortable';}catch{return 'comfortable';}});
 const [streaming,setStreaming]=useState<Record<string,DraftStream>>({}),[sandbox,setSandbox]=useState<Diagnostic>(),[probing,setProbing]=useState(false);
 const messagesEnd=useRef<HTMLDivElement>(null),fileInput=useRef<HTMLInputElement>(null),textarea=useRef<HTMLTextAreaElement>(null),generation=useRef(0),pendingSend=useRef<{body:string;id:string}|undefined>(undefined);
 const notify=useCallback((message:string)=>{setNotice(message);},[]);
 useEffect(()=>{if(!notice)return;const timeout=setTimeout(()=>setNotice(''),7000);return()=>clearTimeout(timeout);},[notice]);
 const [sessionInput,setSessionInput]=useState('');
 async function connectWithSession(value:string){const raw=value.trim();const match=raw.match(/(?:#session=|[?&]session=|enter\/)([0-9a-f]{64})/i)??raw.match(/^([0-9a-f]{64})$/i);const token=match?.[1];if(!token){setFatal('没有识别到启动令牌，请粘贴完整启动地址或 64 位令牌。');return;}try{const response=await fetch('/api/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})});if(!response.ok)throw new Error((await response.json()).message);location.reload();}catch(e){setFatal((e as Error).message);}}
 const refresh=useCallback(async(id=roomId)=>{if(!id)return;const current=generation.current;const data=await client.snapshot(id);if(current===generation.current)setSnapshot(data);},[roomId]);
 const command=useCallback(async(type:Parameters<RoomClient['command']>[0],payload:Record<string,unknown>,id=roomId)=>{const result=await client.command(type,payload,id||undefined);await refresh(id);return result;},[roomId,refresh]);
 useEffect(()=>{void(async()=>{try{const params=new URLSearchParams(location.hash.slice(1));const roomParam=new URLSearchParams(location.search).get('room');const token=params.get('session');if(token){await fetch('/api/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token})}).then(async r=>{if(!r.ok)throw new Error((await r.json()).message);});history.replaceState(null,'',location.pathname+location.search);}const [roomList,agents]=await Promise.all([client.rooms(),client.agents()]);setRooms(roomList);setAllAgents(agents);setRoomId(roomList.find(room=>room.id===roomParam)?.id??roomList[0]?.id??'');setReady(true);}catch(e){setFatal((e as Error).message);}})();},[]);
 useEffect(()=>{
   if(!roomId)return;generation.current++;setSnapshot(undefined);setStreaming({});setReply(undefined);setAttachments([]);let disposed=false,unsubscribe:()=>void=()=>{},timer:ReturnType<typeof setTimeout>|undefined;
   void client.snapshot(roomId).then(data=>{if(disposed)return;setSnapshot(data);unsubscribe=client.subscribe(roomId,data.room.seq,frame=>{
     if(frame.type==='message.delta'){const delta=frame as any;if(delta.roomId===roomId)setStreaming(previous=>appendDraftStream(previous,delta));}
     else if('eventId'in frame){if(frame.type==='chat.message.created'){const id=(frame as any).payload.message.id;setStreaming(prev=>{const next={...prev};delete next[id];return next;});}else if(((frame as any).payload.run&&terminalStates.has((frame as any).payload.run.status))||frame.type==='run.finalized'||frame.type==='run.context.advanced'){const runId=(frame as any).payload.run?.id??(frame as any).payload.runId;setStreaming(previous=>Object.fromEntries(Object.entries(previous).filter(([,stream])=>stream.runId!==runId)));}clearTimeout(timer);timer=setTimeout(()=>{void refresh(roomId).catch(e=>notify(e.message));},60);}
   },value=>{setConnected(value);if(value)setHasConnected(true);});}).catch(e=>notify(e.message));
   return()=>{disposed=true;clearTimeout(timer);unsubscribe();};
 },[roomId]);
 useEffect(()=>{messagesEnd.current?.scrollIntoView({behavior:'smooth',block:'end'});},[snapshot?.messages.length,Object.values(streaming).map(s=>s.text.length).join(',')]);
 const agents=snapshot?.agents??[],messages=snapshot?.messages??[],runs=snapshot?.runs??[],tasks=snapshot?.tasks??[],artifacts=snapshot?.artifacts??[];
 const activeRuns=runs.filter(r=>!terminalStates.has(r.status)),discussion=snapshot?.discussions.find(d=>d.status==='active');
  const runDetail=runs.find(item=>item.id===runDetailId);
  const discussions=snapshot?.discussions??[],discussionDetail=discussions.find(item=>item.id===discussionDetailId);
  const visibleRooms=rooms.filter(room=>room.name.toLowerCase().includes(roomQuery.trim().toLowerCase()));
  useEffect(()=>{if(!roomId)return;const url=new URL(location.href);url.searchParams.set('room',roomId);history.replaceState(null,'',url.toString());},[roomId]);
  useEffect(()=>{const prefix=activeRuns.length?'('+activeRuns.length+') ':'';document.title=snapshot?.room.name?(prefix+snapshot.room.name+' · Tempt Room'):'Tempt Room';},[snapshot?.room.name,activeRuns.length]);
 useEffect(()=>{const handler=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();textarea.current?.focus();}if(event.key==='Escape')setShowMentions(false);if((event.ctrlKey||event.metaKey)&&event.key==='/'){event.preventDefault();setHelpOpen(true);}const target=event.target as HTMLElement|undefined;if(event.key==='?'&&!(target&&['INPUT','TEXTAREA','SELECT'].includes(target.tagName)))setHelpOpen(true);};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler);},[]);
 async function send(){if(!draft.trim()||busy)return;setBusy(true);try{
   const parsedMentions=agents.filter(a=>draft.includes('@'+a.name)||draft.includes('@'+a.id)).map(a=>a.id);
   const payload={text:draft.trim(),mentions:[...new Set([...mentions,...parsedMentions])],replyTo:reply?.id,attachments:attachments.map(a=>a.id)};
   const body=JSON.stringify(payload);if(pendingSend.current?.body!==body)pendingSend.current={body,id:`cmd_${crypto.randomUUID().replaceAll('-','')}`};
   await client.command('message.send',payload,roomId,pendingSend.current.id);pendingSend.current=undefined;setDraft('');setMentions([]);setReply(undefined);setAttachments([]);await refresh();textarea.current?.focus();
 }catch(e){notify((e as Error).message);}finally{setBusy(false);}}
 // Uploads keep the binary outside JSON protocol envelopes.
 async function uploadFile(file?:File){if(!file)return;setBusy(true);try{const data=new FormData();data.append('file',file);const response=await fetch(`/api/rooms/${roomId}/attachments`,{method:'POST',headers:{'Room-Protocol-Version':VERSION},body:data});const body=await response.json();if(!response.ok)throw new Error(body.message);setAttachments(prev=>[...prev,body]);await refresh();}catch(e){notify((e as Error).message);}finally{setBusy(false);if(fileInput.current)fileInput.current.value='';}}
 async function openArtifact(artifact:Artifact){try{setPreview(await client.request(`/api/artifacts/${artifact.id}/preview`));}catch(e){notify((e as Error).message);}}
   async function exportAudit(){if(!roomId||busy)return;setBusy(true);try{const response=await fetch('/api/rooms/'+roomId+'/audit/export',{headers:{'Room-Protocol-Version':VERSION}});if(!response.ok){const body=await response.json().catch(()=>({message:'HTTP '+response.status}));throw new Error(body.message);}const blob=await response.blob();const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=(snapshot?.room.name??roomId)+'-audit.jsonl';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('审计日志已导出');}catch(error){notify((error as Error).message);}finally{setBusy(false);}}
  async function testSandbox(){setProbing(true);try{setSandbox(await client.request('/api/sandbox/probe',{method:'POST',body:'{}'}));}catch(e){notify((e as Error).message);}finally{setProbing(false);}}
 function addAgent(){setDialog(null);setEditing(agentSchema.parse({id:`agent_${crypto.randomUUID().replaceAll('-','')}`,name:'新 Agent',provider:'api'}));}
 if(fatal)return <main className="start-screen"><div className="brand-mark">T</div><h1>重新连接本地工作室</h1><p>{fatal}</p><p className="muted">会话现在会跨重启保持，正常重启无需重新打开。如果浏览器清除了登录状态，可以粘贴启动地址或启动令牌直接连接。</p><div className="form-grid"><input placeholder="粘贴 http://127.0.0.1:4317/#session=… 或 64 位令牌" value={sessionInput} onChange={event=>setSessionInput(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')void connectWithSession(sessionInput);}}/><button className="button" disabled={!sessionInput.trim()} onClick={()=>void connectWithSession(sessionInput)}>连接</button></div><button className="button" onClick={()=>location.reload()}>重新加载</button></main>;
 if(!ready)return <main className="start-screen"><div className="brand-mark">T</div><p>正在连接本地工作室…</p></main>;
 return <div className={`app-shell ${density==='compact'?'compact-density':''}`}>
  <aside className="sidebar">
   <a className="brand" href="/" aria-label="Tempt Room"><span className="brand-mark">T</span><span>tempt<span className="brand-light">room</span><small>一起想清楚，一起完成。</small></span></a>
   <div className="workspace-label"><Icon name="grid" size={16}/><span>本地工作空间</span><span className="local-tag">LOCAL</span></div>
   <div className="section-heading"><span>房间</span><button className="icon-button" aria-label="创建房间" onClick={()=>setDialog('room')}><Icon name="plus" size={16}/></button></div><input className="room-search" value={roomQuery} onChange={event=>setRoomQuery(event.target.value)} placeholder="搜索房间…" aria-label="搜索房间"/>
   <nav className="room-list" aria-label="房间">{visibleRooms.map(room=><button key={room.id} className={`room-link ${room.id===roomId?'selected':''}`} onClick={()=>setRoomId(room.id)}><Icon name="chat" size={17}/><span>{room.name}</span>{room.id===roomId&&<span className="room-indicator"/>}</button>)}{!visibleRooms.length&&<p className="room-search-empty">没有匹配的房间</p>}</nav>
   <button className="new-room" onClick={()=>setDialog('room')}><Icon name="plus" size={15}/> 新建一个房间</button>
   <div className="sidebar-divider"/>
   <div className="section-heading"><span>连接与运行</span></div>
   <button className="sidebar-link" onClick={()=>setDialog('agents')}><Icon name="settings" size={17}/><span>Agent 连接</span><span className="number">{allAgents.filter(a=>a.enabled&&a.provider!=='demo').length}</span></button>
   <button className="sidebar-link" onClick={()=>{setDialog('agents');void testSandbox();}}><Icon name="shield" size={17}/><span>原生沙箱</span><span className={`tiny-dot ${sandbox?.ready?'online':''}`}/></button>
   <button className="sidebar-link" onClick={()=>void client.request<ExecutionSettings>('/api/settings').then(value=>{setSettings(value);setDialog('execution');}).catch(error=>notify(error.message))}><Icon name="task" size={17}/><span>运行设置</span></button>
   <div className="sidebar-spacer"/>
   <div className="sidebar-note"><span className="mini-label">ROOM PROTOCOL / 0.1</span><p>讨论留在房间里，<br/>成果交到你手上。</p><span>本地保存 · 独立工作区</span></div>
   <footer className="owner"><Avatar human/><div><strong>我的工作空间</strong><small>仅本机可访问</small></div><span className={`tiny-dot ${connected?'online':''}`}/></footer>
  </aside>
  <main className="room-main">
   <header className="room-header"><div className="room-title"><span className="room-icon"><Icon name="chat" size={21}/></span><div><h1>{snapshot?.room.name??'正在打开房间'}</h1><p>{snapshot?.room.description||'人和 Agent 的共同工作空间'}</p></div></div><div className="header-actions">{activeRuns.length>0&&<span className="header-activity" title="当前有排队或运行中的 Agent 工作"><span className="tiny-dot working"/>{activeRuns.length} 进行中</span>}<span className="connection"><span className={`tiny-dot ${connected?'online':''}`}/>{connected?'实时连接':hasConnected?'重新连接中':'正在连接'}</span><button className="icon-button" aria-label="切换消息密度" title={density==='compact'?'切换舒适布局':'切换紧凑布局'} onClick={()=>setDensity(previous=>{const next=previous==='compact'?'comfortable':'compact';try{localStorage.setItem('temptroom-density',next);}catch{}return next;})}><Icon name="list" size={17}/></button><button className="icon-button mobile-only" aria-label="打开协作面板" onClick={()=>setMobileDetailsOpen(true)}><Icon name="grid" size={17}/></button><button className="icon-button" aria-label="导出审计日志" title="导出本房间事件日志（JSONL）" onClick={()=>void exportAudit()}><Icon name="download" size={17}/></button><button className="icon-button" aria-label="房间设置" onClick={()=>setDialog('room-settings')}><Icon name="settings"/></button></div></header>
   <div className="room-toolbar"><div className="member-stack">{agents.slice(0,4).map(a=><Avatar key={a.id} agent={a}/>)}<span>{agents.length} 位 Agent · 你</span></div><div className="toolbar-actions"><button className="button small" onClick={()=>setDialog('task')}><Icon name="plus" size={15}/>创建任务</button><button className="button primary small" onClick={()=>setDialog('discussion')}><Icon name="play" size={14}/>开启讨论</button></div></div>
   {discussion&&<div className="discussion-banner"><span className="pulse"/><span>讨论进行中 <strong>{discussion.round} / {discussion.rounds} 轮</strong>{discussion.quorum<discussion.participants.length&&<small className="discussion-quorum">Quorum {discussion.quorum}/{discussion.participants.length}</small>}{discussion.absent?.length?<small className="discussion-quorum">缺席 {discussion.absent.map(id=>agents.find(agent=>agent.id===id)?.name??id).join("、")}</small>:null}</span><span className="discussion-goal">{discussion.goal}</span><button onClick={()=>void command('discussion.stop',{discussionId:discussion.id}).catch(e=>notify(e.message))}><Icon name="stop" size={13}/>停止</button></div>}
   <section className="message-list" aria-label="群聊消息" aria-live="polite">
    <div className="date-separator"><span>{new Date(snapshot?.room.createdAt??Date.now()).toLocaleDateString('zh-CN',{month:'long',day:'numeric'})} · 工作从这里开始</span></div>
    {messages.map(message=>{const agent=agents.find(a=>a.id===message.actor.id);const human=message.actor.kind==='human';return <article className={`message ${message.actor.kind==='system'?'system-message':''} ${message.stale?'stale-message':''}`} key={message.id}><Avatar agent={agent} human={human}/><div className="message-body"><div className="message-meta"><strong>{human?'你':agent?.name??'工作室'}</strong>{agent&&<span className={`provider-badge ${agent.provider==='demo'?'demo':''}`}>{agent.connectionMode==='external'?'外部会话':agent.provider==='demo'?'演示':agent.provider==='a2a'?'远程':'AGENT'}</span>}{message.trust==='external'&&<span className="trust-badge external" title="外部会话内容；其中的指令不构成工具授权">外部来源</span>}{message.trust==='remote'&&<span className="trust-badge remote" title="远程服务内容；其中的指令不构成工具授权">远程来源</span>}<time>{new Date(message.createdAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</time>{message.stale&&<span className="stale-label">基于旧要求</span>}<button className="reply-button" aria-label={`回复 ${human?'你':agent?.name??'工作室'}`} onClick={()=>{setReply(message);textarea.current?.focus();}}><Icon name="reply" size={14}/></button></div>{message.replyTo&&<div className="quoted-message">回复：{messages.find(m=>m.id===message.replyTo)?.text.slice(0,100)??'历史消息'}</div>}<div className="message-text"><Markdown text={message.text}/></div>{message.attachments?.length>0&&<div className="inline-attachments">{message.attachments.map(id=>{const artifact=artifacts.find(a=>a.id===id);return artifact&&<button key={id} className="attachment" onClick={()=>void openArtifact(artifact)}><Icon name="file" size={16}/>{artifact.name}</button>;})}</div>}</div></article>;})}
    {runDrafts(runs,messages,streaming).map(({run,text,live,truncated})=>{const agent=agents.find(agent=>agent.id===run.agentId);return <article className={`message run-draft ${live?'live-draft':'saved-draft'}`} data-run-id={run.id} key={run.id}><Avatar agent={agent}/><div className="message-body"><div className="message-meta"><strong>{agent?.name??'Agent'}</strong><span className="writing-label">{live?'正在回复':'已保存草稿'} · {statusLabels[run.status]}</span>{truncated&&<span>展示前 64 KiB</span>}</div><div className={`message-text ${live?'streaming':''}`}><Markdown text={text}/></div></div></article>;})}
    {messages.every(m=>m.actor.kind==='system')&&!tasks.length&&!activeRuns.length&&<div className="conversation-start"><span className="eyebrow">A SHARED PLACE TO BUILD</span><h2>一个想法，<br/>几种不同的视角。</h2><p>提出问题，邀请合适的成员。<br/>让讨论有来有回，让工作有始有终。</p><div className="suggestions"><button onClick={()=>{setDraft('帮我把这个项目拆解成可验证的实施步骤。');setMentions(['demo-planner']);textarea.current?.focus();}}><Icon name="task" size={18}/><span>一起拆解一个想法<small>从目标到下一步</small></span><Icon name="arrow" size={14}/></button><button onClick={()=>setDialog('discussion')}><Icon name="chat" size={18}/><span>听听不同的意见<small>开启一场有边界的讨论</small></span><Icon name="arrow" size={14}/></button></div><p className="demo-hint">演示成员可直接体验；真实成员在「Agent 连接」中配置。</p></div>}
    {activeRuns.map(run=><div className="run-indicator" key={run.id}><span className="pulse"/><span>{agents.find(a=>a.id===run.agentId)?.name} · {statusLabels[run.status]}{run.contextPending?' · 正在核对新增上下文':''}{run.codex?.phase==='queued'?' · 等待 Codex 空闲':''}</span><button onClick={()=>setRunDetailId(run.id)}>详情</button>{run.status==='waiting_input'&&<button onClick={()=>setTextAction({kind:'input',id:run.id,text:''})}>补充输入</button>}<button onClick={()=>void command('run.cancel',{runId:run.id}).catch(e=>notify(e.message))}>停止</button></div>)}
    {runs.filter(r=>['failed','unknown','interrupted','superseded'].includes(r.status)&&r.error).slice(-2).map(run=><div className="run-error" key={run.id}><Icon name="shield" size={16}/><div><strong>运行记录 · {agents.find(a=>a.id===run.agentId)?.name} · {statusLabels[run.status]}</strong><small>{new Date(run.createdAt).toLocaleString('zh-CN')} · {run.id}</small><p>{run.error}</p><div className="failure-hint"><span className={`failure-label ${classifyFailure(run.error,run.status).kind}`}>{classifyFailure(run.error,run.status).label}</span><small>{classifyFailure(run.error,run.status).advice}</small></div>{['failed','canceled','interrupted','unknown'].includes(run.status)&&<button className="text-button" title="重试会创建一次新运行；状态未知时请先核对是否有副作用" onClick={()=>void command('run.retry',{runId:run.id}).then(()=>notify('已创建重试运行')).catch(error=>notify((error as Error).message))}>重试</button>}<button className="text-button" onClick={()=>setRunDetailId(run.id)}>详情</button>{run.remoteTaskId&&<small>远程任务：{run.remoteTaskId}</small>}{run.codex&&['unknown','interrupted'].includes(run.status)&&<div className="form-grid">{[false,true].map(cancel=><button className="text-button" key={String(cancel)} onClick={()=>void client.request<any>(`/api/runs/${encodeURIComponent(run.id)}/codex/reconcile`,{method:'POST',body:JSON.stringify({cancel})}).then(result=>notify(`核对结果：${result.location} · ${result.phase}`)).catch(error=>notify(error.message))}>{cancel?'核对并停止':'核对状态'}</button>)}</div>}</div></div>)}
    {runs.length>0&&<details className="usage-history"><summary>最近 5 次运行用量</summary>{runs.slice(-5).map(run=><div key={run.id}><strong>{agents.find(agent=>agent.id===run.agentId)?.name} · {statusLabels[run.status]}</strong><RunSummary run={run}/><button className="text-button" onClick={()=>setRunDetailId(run.id)}>详情</button></div>)}</details>}
    <div ref={messagesEnd}/>
   </section>
   <div className="composer-wrap">
    {reply&&<div className="reply-banner"><Icon name="reply" size={15}/><span>{reply.text.slice(0,100)}</span><button className="icon-button" aria-label="取消回复" onClick={()=>setReply(undefined)}><Icon name="close" size={14}/></button></div>}
    <div className="composer"><textarea ref={textarea} aria-label="消息内容" placeholder="写下想法，或 @ 点名一位成员…" value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();void send();}}}/>
     {(mentions.length>0||attachments.length>0)&&<div className="composer-chips">{mentions.map(id=><button key={id} className="mention-chip" onClick={()=>setMentions(m=>m.filter(a=>a!==id))}>@{agents.find(a=>a.id===id)?.name}<Icon name="close" size={12}/></button>)}{attachments.map(a=><button className="mention-chip" key={a.id} onClick={()=>setAttachments(prev=>prev.filter(x=>x.id!==a.id))}><Icon name="file" size={12}/>{a.name}<Icon name="close" size={12}/></button>)}</div>}
     <div className="composer-actions"><div className="composer-tools"><div className="mention-control"><button className={`icon-button mention-toggle ${showMentions?'active':''}`} aria-label="提及 Agent" onClick={()=>setShowMentions(!showMentions)}>＠</button>{showMentions&&<div className="mention-menu">{agents.map(agent=><button key={agent.id} onClick={()=>{if(!agent.enabled){setEditing(agent);setShowMentions(false);return;}setMentions(m=>m.includes(agent.id)?m:[...m,agent.id]);setShowMentions(false);textarea.current?.focus();}}><Avatar agent={agent}/><span>{agent.name}<small>{agent.enabled?agent.role:'需要先配置'}</small></span>{mentions.includes(agent.id)&&<Icon name="check" size={14}/>}</button>)}</div>}</div><button className="icon-button" aria-label="添加附件" disabled={busy||attachments.length>=10} onClick={()=>fileInput.current?.click()}><Icon name="attach"/></button><input type="file" hidden ref={fileInput} onChange={e=>void uploadFile(e.target.files?.[0])}/><span className="composer-mode">{mentions.length?`已点名 ${mentions.length} 位成员${mentions.some(id=>agents.find(a=>a.id===id)?.connectionMode==='external')?' · 外部会话需在线':''}`:'普通消息 · 不自动唤醒 Agent'}</span></div><button className="send-button" aria-label="发送消息" disabled={!draft.trim()||busy} onClick={()=>void send()}><Icon name="send" size={17}/></button></div>
    </div><div className="composer-foot"><span>Enter 发送 · Shift + Enter 换行 · Ctrl/⌘ K 聚焦输入</span><button className="text-button" type="button" onClick={()=>setHelpOpen(true)}>快捷键</button><span><Icon name="shield" size={12}/> {agents.some(agent=>agent.enabled&&agent.executionMode==='host')?'本房间含本机直连成员':'本地执行经过系统沙箱'}</span></div>
   </div>
  </main>
  <aside className="details-panel"><div className="details-heading"><span>共同工作</span><span className="details-mark">↗</span></div>
   <section className="members-section"><div className="section-heading"><span>房间成员</span><button className="text-button" onClick={()=>setDialog('agents')}>管理</button></div><div className="members-list">{agents.map(agent=><button className="member" key={agent.id} onClick={()=>setEditing(agent)}><Avatar agent={agent}/><div><strong>{agent.name}</strong><small>{agent.provider==='demo'?'无模型调用 · 演示':agent.role}</small></div><span className={`tiny-dot ${activeRuns.some(r=>r.agentId===agent.id)?'working':agent.enabled?'online':''}`}/></button>)}</div></section>
   <div className="detail-tabs" role="tablist" aria-label="协作内容"><button role="tab" aria-selected={rightTab==='tasks'} className={rightTab==='tasks'?'active':''} onClick={()=>setRightTab('tasks')}>任务<span>{tasks.length}</span></button><button role="tab" aria-selected={rightTab==='artifacts'} className={rightTab==='artifacts'?'active':''} onClick={()=>setRightTab('artifacts')}>交付物<span>{artifacts.length}</span></button><button role="tab" aria-selected={rightTab==='usage'} className={rightTab==='usage'?'active':''} onClick={()=>setRightTab('usage')}>用量<span>{runs.length}</span></button></div>
   <div className="detail-content">{rightTab==='tasks'?(tasks.length?tasks.map(task=><div className="task-card" key={task.id}><div className="task-card-top"><span className={`status ${task.status}`}>{statusLabels[task.status]??task.status}</span><small>v{task.version}</small></div><h3>{task.title}</h3><p>{task.agentId==='unassigned'?'开放认领':agents.find(a=>a.id===task.agentId)?.name}</p><RunSummary run={runs.findLast(run=>run.taskId===task.id&&run.taskVersion===task.version)}/><div className="task-card-actions">{task.status==='running'&&task.leaseUntil&&<span className="muted">外部租约 {new Date(task.leaseUntil).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</span>}{task.status==='running'&&task.leaseUntil&&<button className="text-button" onClick={()=>void command('task.release',{taskId:task.id}).catch(error=>notify((error as Error).message))}>回收</button>}{task.status==='proposed'&&<button className="text-button" onClick={()=>void command('task.accept',{taskId:task.id}).catch(e=>notify(e.message))}>确认并开始</button>}<select className="task-handoff-select" aria-label="转交给其他成员" title="把任务转交给另一位成员" value="" onChange={event=>{const agentId=event.target.value;if(agentId)void command('task.handoff',{taskId:task.id,agentId}).catch(error=>notify((error as Error).message));}}><option value="">转交给…</option>{agents.filter(a=>a.enabled&&a.id!==task.agentId).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><button className="text-button" onClick={()=>setTextAction({kind:'revise',id:task.id,text:task.title})}>修改目标</button></div></div>):<div className="empty-detail"><span className="empty-icon"><Icon name="task" size={26}/></span><h3>让下一步更明确</h3><p>把讨论中的想法交给一位成员，<br/>在这里追踪进展。</p><button className="button small" onClick={()=>setDialog('task')}><Icon name="plus" size={14}/>创建第一个任务</button></div>):rightTab==='usage'?<UsagePanel runs={runs} agents={agents} settings={settings}/>:(artifacts.length?artifacts.map(artifact=><button className="artifact-row" key={artifact.id} onClick={()=>void openArtifact(artifact)}><span className="artifact-icon"><Icon name="file" size={19}/></span><span><strong>{artifact.name}</strong><small>{artifact.kind==='patch'?'文件差异':artifact.kind==='report'?'报告':'附件'} · {(artifact.size/1024).toFixed(1)} KB{artifact.applied?' · 已应用':''}</small></span><Icon name="arrow" size={14}/></button>):<div className="empty-detail"><span className="empty-icon"><Icon name="file" size={26}/></span><h3>成果会留在这里</h3><p>报告、文件与代码差异，<br/>都能追溯到具体任务。</p></div>)}</div>
   <section className="discussion-history"><div className="section-heading"><span>讨论记录</span><small>{discussions.length?discussions.length+' 场':''}</small></div>{discussions.length?discussions.slice(-3).reverse().map(item=><button className="discussion-row" key={item.id} onClick={()=>setDiscussionDetailId(item.id)}><span className={`status ${item.status==='completed'?'completed':item.status==='active'?'running':'failed'}`}>{item.status==='completed'?'已完成':item.status==='active'?'进行中':'已停止'}</span><strong>{item.goal}</strong><small>{item.round}/{item.rounds} 轮 · Quorum {item.quorum}/{item.participants.length}{item.absent?.length?' · 缺席 '+item.absent.map(id=>agents.find(agent=>agent.id===id)?.name??id).join("、"):''}</small></button>):<p className="muted">还没有讨论记录。</p>}</section>{snapshot&&snapshot.decisions.length>0&&<section className="decisions"><div className="section-heading"><span>共同决策</span></div>{snapshot.decisions.map(d=><div key={d.id}><p>{d.text}</p>{d.accepted?<small className="accepted"><Icon name="check" size={12}/>已接受</small>:<button className="text-button" onClick={()=>void command('decision.accept',{decisionId:d.id}).catch(e=>notify(e.message))}>接受此决策</button>}</div>)}</section>}
   <footer className="details-footer"><Icon name="shield" size={16}/><div><strong>工作有边界，协作更自由</strong><small>独立工作区 · 应用成果前由你确认</small></div></footer>
  </aside>
  {notice&&<div className="toast" role="alert"><span>{notice}</span><button className="icon-button" aria-label="关闭提示" onClick={()=>setNotice('')}><Icon name="close" size={14}/></button></div>}
  {textAction&&<TextActionForm action={textAction} onClose={()=>setTextAction(undefined)} onSubmit={async text=>{try{await command(textAction.kind==='revise'?'task.revise':'run.input',textAction.kind==='revise'?{taskId:textAction.id,title:text}:{runId:textAction.id,text});setTextAction(undefined);}catch(error){notify((error as Error).message);}}}/>}
  {(dialog==='room'||dialog==='room-settings')&&<RoomForm existing={dialog==='room-settings'?snapshot?.room:undefined} agents={allAgents} onClose={()=>setDialog(null)} onSubmit={async payload=>{try{if(dialog==='room-settings'){await command('room.update',{name:payload.name,description:payload.description});await command('room.members.set',{members:payload.members});}else{const receipt=await command('room.create',payload,'');setRoomId(receipt.result.roomId as string);}setRooms(await client.rooms());setDialog(null);}catch(e){notify((e as Error).message);}}}/>}
  {dialog==='discussion'&&<DiscussionForm agents={agents.filter(a=>a.enabled&&a.connectionMode!=='external')} onClose={()=>setDialog(null)} onSubmit={async payload=>{try{await command('discussion.start',payload);setDialog(null);}catch(e){notify((e as Error).message);}}}/>}
  {dialog==='task'&&<TaskForm agents={agents.filter(a=>a.enabled)} tasks={tasks} onClose={()=>setDialog(null)} onSubmit={async payload=>{try{await command('task.create',payload);setDialog(null);setRightTab('tasks');}catch(e){notify((e as Error).message);}}}/>}
  {dialog==='agents'&&<Modal title="连接你的 Agent" subtitle="各自擅长，共同工作。模型与密钥由你配置。" onClose={()=>setDialog(null)}><div className="modal-actions"><button className="button primary" onClick={addAgent}><Icon name="plus" size={15}/>添加 Agent</button></div><div className="connection-list">{allAgents.map(agent=><button key={agent.id} onClick={()=>{setDialog(null);setEditing(agent);}}><Avatar agent={agent}/><span><strong>{agent.name}</strong><small>{providerLabels[agent.provider]}</small></span><span className={`status ${agent.enabled?'completed':''}`}>{agent.enabled?'已启用':'未启用'}</span><Icon name="arrow" size={14}/></button>)}</div><div className="sandbox-section"><div className="form-section-title"><Icon name="shield" size={17}/><strong>Windows 原生沙箱</strong><button className="button small" disabled={probing} onClick={()=>void testSandbox()}>{probing?'验证中…':'运行隔离检查'}</button></div><p className="form-note">只有系统隔离检查通过，本地 Agent 才能运行。工具限制在沙箱内部放宽。</p>{sandbox&&<DiagnosticView report={sandbox}/>}</div></Modal>}
  {editing&&<AgentForm agent={editing} roomId={roomId} isNew={!allAgents.some(agent=>agent.id===editing.id)} onClose={()=>setEditing(undefined)} onNotify={notify} onSave={async agent=>{await command('agent.save',agent as any);setAllAgents(await client.agents());await refresh();setEditing(undefined);notify(allAgents.some(previous=>previous.id===agent.id)?'连接设置已保存':'已添加成员，请在房间设置中邀请');}}/>}
  {dialog==='execution'&&settings&&<ExecutionForm settings={settings} onClose={()=>setDialog(null)} onSave={async value=>{try{await command('settings.update',value);setSettings(value);setDialog(null);notify('运行设置已保存；资源与超时用于新建运行');}catch(error){notify((error as Error).message);}}}/>}
  {preview&&<Modal title={preview.artifact.name} subtitle={`${preview.artifact.kind==='patch'?'代码差异':'交付物'} · ${(preview.artifact.size/1024).toFixed(1)} KB`} onClose={()=>setPreview(undefined)}><div className="artifact-preview">{preview.text!==null?<pre>{preview.text}</pre>:<p>此文件不提供文本预览，可下载查看。</p>}</div><div className="modal-actions"><a className="button" href={`/api/artifacts/${preview.artifact.id}`} download><Icon name="download" size={15}/>下载</a>{preview.artifact.kind==='patch'&&!preview.artifact.applied&&<button className="button primary" onClick={()=>void command('artifact.apply',{artifactId:preview.artifact.id}).then(()=>{setPreview(undefined);notify('成果已应用到原项目');}).catch(e=>notify(e.message))}><Icon name="check" size={15}/>应用到原项目</button>}</div></Modal>}
  {helpOpen&&<Modal title="快捷键与使用提示" subtitle="键盘优先，也可以随时用鼠标操作。" onClose={()=>setHelpOpen(false)}><div className="shortcut-list"><div><kbd>Enter</kbd><span>发送消息</span></div><div><kbd>Shift</kbd><kbd>Enter</kbd><span>换行</span></div><div><kbd>Ctrl/⌘</kbd><kbd>K</kbd><span>聚焦消息输入框</span></div><div><kbd>Ctrl/⌘</kbd><kbd>/</kbd><span>打开本帮助</span></div><div><kbd>Esc</kbd><span>关闭弹窗或提及菜单</span></div><div><kbd>?</kbd><span>在非输入状态打开帮助</span></div></div><p className="form-note">快捷键不会绕过权限、预算或确认流程；所有实际操作仍受房间设置与安全策略约束。</p><div className="modal-actions"><button className="button primary" onClick={()=>setHelpOpen(false)}>知道了</button></div></Modal>}
  {mobileDetailsOpen&&<MobileDetailsModal agents={agents} tasks={tasks} artifacts={artifacts} runs={runs} discussions={discussions} settings={settings} onClose={()=>setMobileDetailsOpen(false)}/>}
  {discussionDetail&&<DiscussionDetailModal discussion={discussionDetail} agents={agents} runs={runs} messages={messages} onClose={()=>setDiscussionDetailId(undefined)}/>}
  {runDetail&&<RunDetailModal run={runDetail} agents={agents} onClose={()=>setRunDetailId(undefined)} onRetry={()=>void command('run.retry',{runId:runDetail.id}).then(()=>{setRunDetailId(undefined);notify('已创建重试运行');}).catch(error=>notify((error as Error).message))} onCancel={()=>void command('run.cancel',{runId:runDetail.id}).catch(error=>notify((error as Error).message))}/>}
 </div>;
}
function RunDetailModal({run,agents,onClose,onRetry,onCancel}:{run:Run;agents:AgentDescriptor[];onClose:()=>void;onRetry:()=>void;onCancel:()=>void}){
 const [operations,setOperations]=useState<ToolOperation[]|null>(null);
 useEffect(()=>{let active=true;client.request<ToolOperation[]>(`/api/runs/${encodeURIComponent(run.id)}/operations`).then(value=>{if(active)setOperations(value);}).catch(()=>{if(active)setOperations([]);});return()=>{active=false;};},[run.id]);
 const agent=agents.find(item=>item.id===run.agentId);
 const retryable=['failed','canceled','interrupted','unknown'].includes(run.status);
 const active=!terminalStates.has(run.status);
 const operationStatus=(status:ToolOperation['status'])=>status==='completed'?'completed':status==='unknown'?'failed':'queued';
 return <Modal title="运行详情" subtitle={`${agent?.name??run.agentId} · ${statusLabels[run.status]??run.status} · ${run.id}`} onClose={onClose}>
  <div className="run-detail">
   <div className="run-detail-grid">
    <div><small>创建时间</small><span>{new Date(run.createdAt).toLocaleString('zh-CN')}</span></div>
    <div><small>更新时间</small><span>{new Date(run.updatedAt).toLocaleString('zh-CN')}</span></div>
    <div><small>任务</small><span>{run.taskId?`${run.taskId} · v${run.taskVersion??'?'}`:'无（聊天运行）'}</span></div>
    <div><small>上下文</small><span>{run.contextSeq!==undefined?`seq ${run.contextSeq}${run.contextRound?` · 对账 ${run.contextRound} 轮`:''}`:'—'}</span></div>
   </div>
   <div className="run-detail-block"><small>提示词</small><pre>{run.prompt}</pre></div>
   {run.error&&<div className="run-detail-block error"><small>错误原文 · {classifyFailure(run.error,run.status).label}</small><pre>{run.error}</pre><p className="muted">{classifyFailure(run.error,run.status).advice}</p></div>}
   <RunSummary run={run}/>
   <div className="run-detail-block"><div className="form-section-title"><strong>Room 工具操作</strong><small>{operations===null?'读取中…':`${operations.length} 条`}</small></div>{operations?.length?<div className="run-operations">{operations.map(operation=><div key={operation.operationId}><code>{operation.name}</code><span className={`status ${operationStatus(operation.status)}`}>{operation.status}</span><small>{new Date(operation.createdAt).toLocaleTimeString('zh-CN')}</small></div>)}</div>:<p className="muted">{operations===null?'读取中…':'本次运行没有 Room 写工具操作记录。'}</p>}</div>
  </div>
  <div className="modal-actions"><button className="button" onClick={onClose}>关闭</button>{active&&<button className="button" onClick={onCancel}>停止运行</button>}{retryable&&<button className="button primary" onClick={onRetry}>重试运行</button>}</div>
 </Modal>;
}
function MobileDetailsModal({agents,tasks,artifacts,runs,discussions,settings,onClose}:{agents:AgentDescriptor[];tasks:Task[];artifacts:Artifact[];runs:Run[];discussions:Discussion[];settings?:ExecutionSettings;onClose:()=>void}){
 return <Modal title="协作面板" subtitle="移动端的任务、成果、讨论和用量" onClose={onClose}>
  <div className="mobile-details">
   <section><h3>成员 <small>{agents.length}</small></h3><div className="mobile-members">{agents.map(agent=><span key={agent.id}><Avatar agent={agent}/>{agent.name}</span>)}</div></section>
   <section><h3>任务 <small>{tasks.length}</small></h3>{tasks.length?tasks.slice(-8).reverse().map(task=><div className="mobile-row" key={task.id}><span className={`status ${task.status}`}>{statusLabels[task.status]??task.status}</span><strong>{task.title}</strong><small>v{task.version}</small></div>):<p className="muted">还没有任务。</p>}</section>
   <section><h3>交付物 <small>{artifacts.length}</small></h3>{artifacts.length?artifacts.slice(-8).reverse().map(artifact=><div className="mobile-row" key={artifact.id}><strong>{artifact.name}</strong><small>{artifact.kind} · {(artifact.size/1024).toFixed(1)} KB</small></div>):<p className="muted">还没有交付物。</p>}</section>
   <section><h3>讨论 <small>{discussions.length}</small></h3>{discussions.length?discussions.slice(-5).reverse().map(item=><div className="mobile-row" key={item.id}><strong>{item.goal}</strong><small>{item.round}/{item.rounds} 轮 · Quorum {item.quorum}/{item.participants.length}</small></div>):<p className="muted">还没有讨论。</p>}</section>
   <section><h3>用量</h3><UsagePanel runs={runs} agents={agents} settings={settings}/></section>
  </div>
  <div className="modal-actions"><button className="button" onClick={onClose}>关闭</button></div>
 </Modal>;
}
function DiscussionDetailModal({discussion,agents,runs,messages,onClose}:{discussion:Discussion;agents:AgentDescriptor[];runs:Run[];messages:Message[];onClose:()=>void}){
 const relatedRuns=runs.filter(run=>run.discussionId===discussion.id),runIds=new Set(relatedRuns.map(run=>run.id)),relatedMessages=messages.filter(message=>message.runId&&runIds.has(message.runId));
 return <Modal title="讨论详情" subtitle={`${discussion.round}/${discussion.rounds} 轮 · Quorum ${discussion.quorum}/${discussion.participants.length}`} onClose={onClose}>
  <div className="discussion-detail">
   <div className="run-detail-block"><small>讨论目标</small><pre>{discussion.goal}</pre></div>
   <div className="run-detail-grid"><div><small>状态</small><span>{discussion.status}</span></div><div><small>缺席</small><span>{discussion.absent?.length?discussion.absent.map(id=>agents.find(agent=>agent.id===id)?.name??id).join("、"):'无'}</span></div></div>
   <div className="run-detail-block"><small>轮次运行</small>{relatedRuns.length?<div className="run-operations">{relatedRuns.map(run=><div key={run.id}><code>{agents.find(agent=>agent.id===run.agentId)?.name??run.agentId} · 第 {run.round??'?'} 轮</code><span className={`status ${run.status==='completed'?'completed':run.status==='failed'?'failed':'queued'}`}>{statusLabels[run.status]??run.status}</span></div>)}</div>:<p className="muted">没有关联运行。</p>}</div>
   <div className="run-detail-block"><small>发言记录</small>{relatedMessages.length?<div className="discussion-messages">{relatedMessages.map(message=><div key={message.id}><strong>{agents.find(agent=>agent.id===message.actor.id)?.name??message.actor.id}</strong><p>{message.text.slice(0,500)}</p></div>)}</div>:<p className="muted">没有关联发言。</p>}</div>
  </div>
  <div className="modal-actions"><button className="button" onClick={onClose}>关闭</button></div>
 </Modal>;
}
function UsagePanel({runs,agents,settings}:{runs:Run[];agents:AgentDescriptor[];settings?:ExecutionSettings}){
 const withUsage=runs.filter(run=>run.usage);
 const tokenRuns=withUsage.filter(run=>run.usage?.inputTokens!==undefined||run.usage?.outputTokens!==undefined);
 const inputTokens=tokenRuns.reduce((sum,run)=>sum+(run.usage?.inputTokens??0),0);
 const outputTokens=tokenRuns.reduce((sum,run)=>sum+(run.usage?.outputTokens??0),0);
 const costRuns=withUsage.filter(run=>run.usage?.costUsd!==undefined);
 const cost=costRuns.reduce((sum,run)=>sum+(run.usage?.costUsd??0),0);
 const unknown=runs.length-withUsage.length;
 const failures=new Map<string,number>();for(const run of runs){if(!['failed','interrupted','unknown'].includes(run.status))continue;const label=classifyFailure(run.error,run.status).label;failures.set(label,(failures.get(label)??0)+1);}
 const failureEntries=[...failures.entries()].sort((a,b)=>b[1]-a[1]);
 const rows=agents.map(agent=>{const own=runs.filter(run=>run.agentId===agent.id),known=own.filter(run=>run.usage);return {agent,runs:own.length,known:known.length,input:known.reduce((sum,run)=>sum+(run.usage?.inputTokens??0),0),output:known.reduce((sum,run)=>sum+(run.usage?.outputTokens??0),0),cost:known.reduce((sum,run)=>sum+(run.usage?.costUsd??0),0),hasCost:known.some(run=>run.usage?.costUsd!==undefined)};}).filter(row=>row.runs>0).sort((a,b)=>(b.input+b.output)-(a.input+a.output));
 return <div className="usage-panel"><div className="usage-totals"><div><small>输入 Token</small><strong>{tokenRuns.length?inputTokens.toLocaleString():'未知'}</strong></div><div><small>输出 Token</small><strong>{tokenRuns.length?outputTokens.toLocaleString():'未知'}</strong></div><div><small>费用估值</small><strong>{costRuns.length?'US$ '+cost.toFixed(4):'未知'}</strong></div><div><small>已记录运行</small><strong>{withUsage.length} / {runs.length}</strong></div></div><p className="usage-note">费用与 Token 来自提供方上报；未知的提供方不会按 0 计入。{unknown?` 还有 ${unknown} 次运行未返回用量。`:' 当前所有运行均已返回用量。'}</p><p className="usage-budget">单次运行预算：{settings?(settings.tokenBudget||settings.costBudgetUsd?[settings.tokenBudget?settings.tokenBudget.toLocaleString()+' Token':'',settings.costBudgetUsd?'US$ '+settings.costBudgetUsd.toFixed(2):''].filter(Boolean).join(' · '):'未设置硬上限'):'打开运行设置后显示'}</p>{rows.length?<div className="usage-rows">{rows.map(row=><div className="usage-row" key={row.agent.id}><strong>{row.agent.name}<small>{row.runs} 次运行 · {row.known} 次已上报</small></strong><span>Token 入 {row.known?row.input.toLocaleString():'未知'} · 出 {row.known?row.output.toLocaleString():'未知'}{row.hasCost?' · US$ '+row.cost.toFixed(4):''}</span></div>)}</div>:<div className="empty-detail"><span className="empty-icon"><Icon name="task" size={24}/></span><h3>还没有可汇总的运行</h3><p>发起一次对话或任务后，<br/>这里会显示成员的 Token 与费用用量。</p></div>}<div className="usage-failures"><strong>失败分类</strong>{failureEntries.length?<div className="failure-chips">{failureEntries.map(([label,count])=><span key={label}><em>{label}</em>{count}</span>)}</div>:<p className="usage-note">最近没有失败运行。</p>}</div></div>;
}
function DiagnosticView({report}:{report:Diagnostic}){return <div className="diagnostics"><strong className={report.ready?'success-text':'warning-text'}>{report.ready?'检查通过':'尚未就绪'}</strong>{report.checks.map((check,index)=><div key={index}><span className={check.passed?'success-text':'warning-text'}>{check.passed?'✓':'–'}</span><span><strong>{check.name}</strong><small>{check.detail}</small></span></div>)}<small className="muted">{new Date(report.checkedAt).toLocaleString('zh-CN')}</small></div>;}
function RunSummary({run}:{run?:Run}){
 if(!run)return null;
 const usage=run.usage;
 const scope=usage?.scope==='last-request'?'最近模型请求 · ':usage?.scope==='session-total'?'会话累计 · ':'';
 const usageText=usage?`${scope}Token 入 ${usage.inputTokens?.toLocaleString()??'未知'} · 出 ${usage.outputTokens?.toLocaleString()??'未知'}`:'Token 用量未返回';
 const costText=usage?.costUsd!==undefined?`费用 US$ ${usage.costUsd.toFixed(4)}`:'费用未知';
 const limits=run.limits?`限额 ${(run.limits.memoryMb/1024).toFixed(1)} GiB · ${Math.round(run.limits.timeoutMs/60000)} 分钟${run.limits.tokenBudget||run.limits.costBudgetUsd?' · 预算 '+[run.limits.tokenBudget?run.limits.tokenBudget.toLocaleString()+' Token':'',run.limits.costBudgetUsd?'US$ '+run.limits.costBudgetUsd.toFixed(2):''].filter(Boolean).join(' / '):''}`:'';
 return <div className="run-summary"><small>{usageText} · {costText}</small>{limits&&<small>{limits}</small>}{run.contextRound?<small>额外对账 {run.contextRound} 轮 · 用量为最近一次上报</small>:null}</div>;
}
function ExecutionForm({settings,onClose,onSave}:{settings:ExecutionSettings;onClose:()=>void;onSave:(value:ExecutionSettings)=>Promise<void>}){
 const supportsContext=Boolean(settings.contextPolicy),[value,setValue]=useState(()=>executionSettingsSchema.parse(settings)),[busy,setBusy]=useState(false);
 const update=(key:keyof ExecutionSettings,number:number)=>setValue(previous=>({...previous,[key]:number}));
 return <Modal title="运行设置" subtitle="控制同时进行的工作，以及每次执行的资源。" onClose={onClose}><form className="form" onSubmit={event=>{event.preventDefault();setBusy(true);const {contextPolicy,...legacy}=value;void onSave(supportsContext?value:legacy as ExecutionSettings).finally(()=>setBusy(false));}}>
  <div className="form-grid"><label>同时运行数量<input type="number" required min={1} max={8} value={value.concurrency} onChange={event=>update('concurrency',Number(event.target.value))}/></label><label>单次内存上限（GiB）<input type="number" required min={0.25} max={16} step={0.25} value={value.memoryMb/1024} onChange={event=>update('memoryMb',Math.round(Number(event.target.value)*1024))}/></label><label>单次进程数量上限<input type="number" required min={1} max={128} value={value.maxProcesses} onChange={event=>update('maxProcesses',Number(event.target.value))}/></label><label>代码任务超时（分钟）<input type="number" required min={1} max={120} value={value.taskTimeoutMs/60000} onChange={event=>update('taskTimeoutMs',Number(event.target.value)*60000)}/></label><label>聊天运行超时（分钟）<input type="number" required min={1} max={120} value={value.chatTimeoutMs/60000} onChange={event=>update('chatTimeoutMs',Number(event.target.value)*60000)}/></label><label>外部任务租约（分钟）<input type="number" required min={1} max={1440} value={value.taskLeaseMs/60000} onChange={event=>update('taskLeaseMs',Math.round(Number(event.target.value)*60000))}/></label><label>单次运行 Token 上限（0=不限）<input type="number" required min={0} max={100000000} step={1000} value={value.tokenBudget} onChange={event=>update('tokenBudget',Math.floor(Number(event.target.value)))}/></label><label>单次运行费用上限（US$，0=不限）<input type="number" required min={0} max={1000000} step={0.01} value={value.costBudgetUsd} onChange={event=>update('costBudgetUsd',Number(event.target.value))}/></label><label>单成员待处理运行上限<input type="number" required min={1} max={100} value={value.maxQueuedRunsPerAgent} onChange={event=>update('maxQueuedRunsPerAgent',Math.floor(Number(event.target.value)))}/></label><label>房间待处理运行上限<input type="number" required min={1} max={500} value={value.maxQueuedRunsPerRoom} onChange={event=>update('maxQueuedRunsPerRoom',Math.floor(Number(event.target.value)))}/></label><label>单成员每分钟运行上限<input type="number" required min={1} max={1000} value={value.maxAgentRunsPerMinute} onChange={event=>update('maxAgentRunsPerMinute',Math.floor(Number(event.target.value)))}/></label><label className="checkbox-label"><input type="checkbox" checked={value.adaptiveTimeouts} onChange={event=>setValue(previous=>({...previous,adaptiveTimeouts:event.target.checked}))}/>根据历史运行时长自适应超时（仅缩短，不超过配置上限）</label><label className="checkbox-label"><input type="checkbox" checked={value.autoRetryChatRuns} onChange={event=>setValue(previous=>({...previous,autoRetryChatRuns:event.target.checked}))}/>自动重试纯讨论运行（仅演示/API、沙箱模式）</label><label className="checkbox-label"><input type="checkbox" checked={value.allowAgentMentionsToWake} onChange={event=>setValue(previous=>({...previous,allowAgentMentionsToWake:event.target.checked}))}/>允许 Agent 提及唤醒其他成员（受链深与速率限制）</label><label className="checkbox-label"><input type="checkbox" checked={value.recoverInterruptedChatRuns} onChange={event=>setValue(previous=>({...previous,recoverInterruptedChatRuns:event.target.checked}))}/>服务重启后恢复纯讨论运行（仅演示/API、沙箱模式）</label><label>最大唤醒链深<input type="number" required min={1} max={10} value={value.maxWakeChainDepth} onChange={event=>update('maxWakeChainDepth',Math.floor(Number(event.target.value)))}/></label><label>工具结果上限（KiB）<input type="number" required min={64} max={8192} value={Math.round(value.maxToolResultBytes/1024)} onChange={event=>update('maxToolResultBytes',Number(event.target.value)*1024)}/></label><label>单次运行工具调用上限<input type="number" required min={1} max={10000} value={value.maxToolCallsPerRun} onChange={event=>update('maxToolCallsPerRun',Math.floor(Number(event.target.value)))}/></label><label>上下文保留消息数<input type="number" required min={1} max={200} value={value.maxContextMessages} onChange={event=>update('maxContextMessages',Math.floor(Number(event.target.value)))}/></label><label>最多自动重试次数<input type="number" required min={0} max={3} value={value.maxAutoRetries} onChange={event=>update('maxAutoRetries',Math.floor(Number(event.target.value)))}/></label><label>房间累计 Token 上限（0=不限）<input type="number" required min={0} max={1000000000} step={1000} value={value.roomTokenBudget} onChange={event=>update('roomTokenBudget',Math.floor(Number(event.target.value)))}/></label><label>房间累计费用上限（US$，0=不限）<input type="number" required min={0} max={1000000} step={0.01} value={value.roomCostBudgetUsd} onChange={event=>update('roomCostBudgetUsd',Number(event.target.value))}/></label></div>
  {supportsContext&&<fieldset><legend>上下文对账</legend><div className="form-grid"><label>允许落后的事件数<input type="number" required min={1} max={10000} value={value.contextPolicy.maxLag} onChange={event=>setValue(previous=>({...previous,contextPolicy:{...previous.contextPolicy,maxLag:Number(event.target.value)}}))}/></label><label>最多额外对账轮次<input type="number" required min={0} max={12} value={value.contextPolicy.maxRounds} onChange={event=>setValue(previous=>({...previous,contextPolicy:{...previous.contextPolicy,maxRounds:Number(event.target.value)}}))}/></label></div><p className="form-note">新增已接受决策和针对成员的提及会要求重新对账；额外轮次会调用已配置模型，并沿用本次任务的总超时。</p></fieldset>}
  <p className="form-note">同一房间中的同一成员保持串行。资源、超时、单次/房间累计预算、队列上限和对账策略在创建运行时保存；房间累计预算按已知用量在入队前熔断，修改不会中断现有运行；预算只按提供方上报的用量判断，0 表示不限。外部 Agent 认领任务后需在租约内心跳，过期会被回收为开放任务。网络和文件隔离仍由系统沙箱执行。</p><div className="modal-actions"><button type="button" className="button" onClick={onClose}>取消</button><button className="button primary" disabled={busy}>保存设置</button></div>
 </form></Modal>;
}
function TextActionForm({action,onClose,onSubmit}:{action:{kind:'revise'|'input';text:string};onClose:()=>void;onSubmit:(text:string)=>Promise<void>}){
 const [text,setText]=useState(action.text),[busy,setBusy]=useState(false);const revise=action.kind==='revise';
 return <Modal title={revise?'修改任务目标':'补充输入'} subtitle={revise?'旧运行会停止，结果保留为旧版本。已确认的依赖下游任务也会创建新版本并重新排队。':'输入会保存到当前房间并发给等待中的 Agent，请勿输入密钥。'} onClose={onClose}><form className="form" onSubmit={event=>{event.preventDefault();setBusy(true);void onSubmit(text).finally(()=>setBusy(false));}}><label>{revise?'新的任务目标':'补充内容'}<textarea required autoFocus rows={5} maxLength={revise?5000:16000} value={text} onChange={event=>setText(event.target.value)}/></label><div className="modal-actions"><button type="button" className="button" onClick={onClose}>取消</button><button className="button primary" disabled={busy||!text.trim()}>{revise?'创建新版本':'发送补充输入'}</button></div></form></Modal>;
}
function AgentForm({agent,roomId,isNew=false,onClose,onSave,onNotify}:{agent:AgentDescriptor;roomId:string;isNew?:boolean;onClose:()=>void;onSave:(agent:AgentDescriptor)=>Promise<void>;onNotify:(text:string)=>void}){
 const [value,setValue]=useState({...agent,runtimeDirectory:agent.runtimeDirectory??''}),[report,setReport]=useState<Diagnostic>(),[busy,setBusy]=useState(false),[connect,setConnect]=useState(''),[installTarget,setInstallTarget]=useState('claude'),[projectDir,setProjectDir]=useState(''),[previewText,setPreviewText]=useState('');const update=(key:string,v:any)=>setValue(old=>({...old,[key]:v}));
 const external=value.connectionMode==='external',attached=value.connectionMode==='attach';
 const local=!external&&!attached&&['codex','claude','deepseek'].includes(value.provider);
 async function inspect(protocol=false){setBusy(true);try{await client.command('agent.save',value as any);setReport(await client.request<Diagnostic>(`/api/agents/${agent.id}/${protocol?'protocol-probe':'diagnostics'}`,protocol?{method:'POST',body:'{}'}:undefined));}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 async function showConnect(){setBusy(true);try{const data=await client.request<any>(`/api/agents/${encodeURIComponent(agent.id)}/connect?roomId=${encodeURIComponent(roomId)}`);setConnect([`# ${agent.name} 外部 MCP 接入（房间 ${roomId}）`,`# 令牌只代表该 Agent、只能访问该房间，服务重启后失效。`,`# 外部 Agent 使用自己的权限、目录和登录状态；Tempt Room 不托管其进程，也不会自动唤醒空闲 Agent。`,``,`## Claude Code`,data.snippets.claude,``,`## Codex`,data.snippets.codex,``,`## DSH`,data.snippets.dsh,``,`## 自动值守（可选）`,data.snippets.runner].join('\n'));}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 async function copyConnect(){try{await navigator.clipboard.writeText(connect);onNotify('外部接入配置已复制');}catch{onNotify('浏览器未授权剪贴板，请手动选择文本复制');}}
 async function writeConnect(){setBusy(true);try{const data=await client.request<any>(`/api/agents/${encodeURIComponent(agent.id)}/connect/write`,{method:'POST',body:JSON.stringify({roomId})});onNotify('已写入 '+data.dir);setConnect(connect+`\n\n# 已写入管理目录：\n# ${data.dir}\n# ${data.files.join(' / ')}`);}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 async function installConnector(){if(!window.confirm(`将把 room MCP 配置写入 ${installTarget} 的客户端配置（会先备份文件），确定继续？`))return;setBusy(true);try{const projectPath=installTarget==='claude-project'?projectDir:undefined;if(installTarget==='claude-project'&&!projectDir){onNotify('请先填写项目目录');return;}const data=await client.request<any>(`/api/agents/${encodeURIComponent(agent.id)}/connect/install`,{method:'POST',body:JSON.stringify({roomId,target:installTarget,...(projectPath?{projectPath}:{})})});onNotify(`已安装到 ${data.path}${data.backup?'；备份：'+data.backup:''}`);}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 async function previewInstall(){setBusy(true);try{if(installTarget==='claude-project'&&!projectDir){onNotify('请先填写项目目录');return;}const projectPath=installTarget==='claude-project'?projectDir:undefined;const data=await client.request<any>(`/api/agents/${encodeURIComponent(agent.id)}/connect/preview`,{method:'POST',body:JSON.stringify({roomId,target:installTarget,...(projectPath?{projectPath}:{})})});setPreviewText(`# ${data.path}\n# ${data.note??(data.changed?'将修改':'无需修改')}\n\n--- 当前 ---\n${data.current||'(文件不存在)'}\n\n--- 安装后 ---\n${data.planned}`);}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 async function uninstallConnector(){if(!window.confirm(`从 ${installTarget} 的客户端配置中移除本工具的 room MCP 条目？`))return;setBusy(true);try{const projectPath=installTarget==='claude-project'?projectDir:undefined;if(installTarget==='claude-project'&&!projectDir){onNotify('请先填写项目目录');return;}const data=await client.request<any>(`/api/agents/${encodeURIComponent(agent.id)}/connect/uninstall`,{method:'POST',body:JSON.stringify({target:installTarget,...(projectPath?{projectPath}:{})})});onNotify(`已移除${data.detail?'（'+data.detail+'）':''}`);}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 async function detect(){setBusy(true);try{const data=await client.request<any>('/api/agents/autodetect');const path=data.executable?.[value.provider];if(path){update('executable',path);onNotify('已填入本机程序：'+path);}else{onNotify('未自动找到'+providerLabels[value.provider]+'程序，请手动填写路径');}}catch(error){onNotify((error as Error).message);}finally{setBusy(false);}}
 return <Modal title={isNew?'添加 Agent':`${agent.name} · 连接设置`} subtitle={providerLabels[value.provider]} onClose={onClose}>
  <form className="form" onSubmit={e=>{e.preventDefault();setBusy(true);void onSave(value).catch(e=>onNotify(e.message)).finally(()=>setBusy(false));}}>
   {isNew&&<><label>Agent 类型<select value={value.provider} onChange={e=>{setValue(previous=>({...previous,provider:e.target.value as AgentDescriptor['provider'],model:'',endpoint:'',executable:'',runtimeDirectory:'',version:'',credentialEnv:'',capabilities:undefined,connectionMode:'managed',codexBinding:undefined}));setReport(undefined);setConnect('');}}>{Object.entries(providerLabels).filter(([provider])=>provider!=='demo').map(([provider,label])=><option key={provider} value={provider}>{label}</option>)}</select></label><p className="form-note">可以添加多个同类 Agent，分别设置模型、职责和接入方式。保存后在「房间设置」邀请该成员。新成员默认未启用。</p></>}
   <div className="form-grid"><label>显示名称<input required value={value.name} onChange={e=>update('name',e.target.value)}/></label><label>调度权重（0.1–10）<input type="number" required min={0.1} max={10} step={0.1} value={value.schedulerWeight??1} onChange={e=>update('schedulerWeight',Number(e.target.value))}/></label><label>房间工具权限<select value={value.roomToolPolicy??'allow'} onChange={event=>update('roomToolPolicy',event.target.value as AgentDescriptor['roomToolPolicy'])}><option value="allow">允许读写</option><option value="read-only">只读</option><option value="deny">禁止</option></select></label><div className="tool-allowlist"><span>允许的房间工具</span>{roomToolNames.map(tool=><label key={tool}><input type="checkbox" checked={(value.allowedRoomTools??roomToolNames).includes(tool)} onChange={event=>{const current=value.allowedRoomTools??[...roomToolNames];const next=event.target.checked?[...current,tool]:current.filter(item=>item!==tool);if(next.length)update('allowedRoomTools',next as AgentDescriptor['allowedRoomTools']);}}/>{roomToolLabels[tool]}</label>)}<label>单条发言上限（字符）<input type="number" required min={1} max={32000} value={value.maxRoomPostChars??32000} onChange={event=>update('maxRoomPostChars',Math.floor(Number(event.target.value)))}/></label><label>任务标题上限（字符）<input type="number" required min={1} max={5000} value={value.maxTaskTitleChars??5000} onChange={event=>update('maxTaskTitleChars',Math.floor(Number(event.target.value)))}/></label></div>{!external&&!attached&&<label>模型名称<input placeholder="留空使用默认模型" value={value.model} onChange={e=>update('model',e.target.value)}/></label>}</div>
   <label>接入方式<select value={value.connectionMode??'managed'} onChange={e=>{const mode=e.target.value as AgentDescriptor['connectionMode'];setValue(previous=>({...previous,connectionMode:mode,...(mode==='attach'?{executionMode:'host',codexBinding:previous.codexBinding??{transport:'websocket',endpoint:'ws://127.0.0.1:4500',credentialEnv:'ROOM_CODEX_ATTACH_TOKEN',threadId:'',expectedCwd:''}}:{})}));setReport(undefined);}}><option value="managed">由 Tempt Room 启动</option><option value="external">外部会话 / MCP</option>{value.provider==='codex'&&<option value="attach">附着已有 Codex 线程</option>}</select></label>
   {attached&&<><p className="form-note">连接已经持有目标线程的 App Server，沿用原有目录与权限。不会启动替代线程，不代表沙箱隔离。本模式不接管审批和补充输入，需在原 Codex 客户端核验。</p><label>传输方式<select value={value.codexBinding?.transport??'websocket'} onChange={e=>setValue(previous=>({...previous,codexBinding:{...previous.codexBinding!,transport:e.target.value as 'websocket'|'control-socket',endpoint:''}}))}><option value="websocket">认证 WebSocket（loopback）</option><option value="control-socket">官方 control socket / proxy</option></select></label><label>已有后端端点<input required placeholder={value.codexBinding?.transport==='websocket'?'ws://127.0.0.1:4500':'控制 socket 绝对路径'} value={value.codexBinding?.endpoint??''} onChange={e=>setValue(previous=>({...previous,codexBinding:{...previous.codexBinding!,endpoint:e.target.value}}))}/></label>{value.codexBinding?.transport==='websocket'&&<label>连接令牌环境变量名称<input required placeholder="ROOM_CODEX_ATTACH_TOKEN" value={value.codexBinding?.credentialEnv??''} onChange={e=>setValue(previous=>({...previous,codexBinding:{...previous.codexBinding!,credentialEnv:e.target.value}}))}/></label>}<label>已有线程 ID<input required value={value.codexBinding?.threadId??''} onChange={e=>setValue(previous=>({...previous,codexBinding:{...previous.codexBinding!,threadId:e.target.value}}))}/></label><label>线程当前工作目录<input required placeholder="绝对路径，必须与后端报告一致" value={value.codexBinding?.expectedCwd??''} onChange={e=>setValue(previous=>({...previous,codexBinding:{...previous.codexBinding!,expectedCwd:e.target.value}}))}/></label><label>固定后端版本（可选）<input value={value.version} onChange={e=>update('version',e.target.value)}/></label>{value.codexBinding?.transport==='control-socket'&&<label>Codex 程序绝对路径<input required value={value.executable} onChange={e=>update('executable',e.target.value)}/></label>}</>}
   {external&&<p className="form-note">使用当前会话读写房间；模型和本机工具由外部会话负责。空闲会话不会自动唤醒。</p>}
   {!external&&value.provider==='deepseek'&&<p className="form-note">模型名需与 ACP 返回的选项名称一致，也可填写完整选项值；留空沿用默认模型。Desktop 请选择安装目录中的 DeepSeek Harness.exe，应用会识别 CLI 启动方式。</p>}
   <label>在团队中的职责<textarea rows={2} value={value.role} onChange={e=>update('role',e.target.value)}/></label>
   {local&&<><label>{value.provider==='deepseek'?'程序入口（Desktop exe 或官方 npm 包 JS）':'原生可执行文件'}<input placeholder={value.provider==='deepseek'?'D:\Program Files\Deepseek Harness\DeepSeek Harness.exe':'例如 C:\tools\agent.exe'} value={value.executable} onChange={e=>update('executable',e.target.value)}/></label><label>完整运行文件目录（可选）<input placeholder={value.provider==='deepseek'?'Desktop 自动识别；npm 需指定包含全部依赖的专用目录':'需要附带运行文件时指定，仅复制到沙箱'} value={value.runtimeDirectory} onChange={e=>update('runtimeDirectory',e.target.value)}/></label><label>固定版本（可选）<input placeholder="记录验收版本；npm 包与 Claude/Codex 版本查询会核对" value={value.version} onChange={e=>update('version',e.target.value)}/></label><div className="form-grid"><button type="button" className="button" disabled={busy} onClick={()=>void detect()}>自动探测本机程序</button></div><label>执行权限<select value={value.executionMode??'sandbox'} onChange={e=>update('executionMode',e.target.value)}><option value="sandbox">沙箱隔离（默认，受限文件/网络/工具）</option><option value="host">本机直连 · 当前用户完整权限（高风险）</option></select></label>{value.executionMode==='host'&&<p className="form-note">本机直连：不复制运行文件、不建快照，Agent 以当前用户身份直接运行。它可读写本机文件、访问 localhost、使用已安装工具和自身登录状态，并直接修改真实项目目录。只对可信 Agent 开启。</p>}</>}
   {!external&&['api','a2a'].includes(value.provider)&&<label>{value.provider==='api'?'API 基址（例如 https://api.example.com/v1）':'Agent Card 地址或服务基址'}<input type="url" placeholder="https://" value={value.endpoint} onChange={e=>update('endpoint',e.target.value)}/></label>}
   {!external&&value.provider==='api'&&<><label>回复方式<select value={value.responseFormat??'text'} onChange={event=>update('responseFormat',event.target.value)}><option value="text">文本讨论 · 流式回复</option><option value="room-json">结构化回复与文本交付物</option></select></label><p className="form-note">结构化方式需要端点支持 JSON 回复模式，完整校验后显示消息和交付物；不提供代码执行工具。</p></>}
    {!external&&!attached&&(value.provider==='claude'||value.provider==='codex')&&<label>{value.provider==='claude'?'Anthropic 兼容端点（可选，如 DeepSeek /anthropic）':'OpenAI 兼容端点（可选）'}<input type="url" placeholder={value.provider==='claude'?'https://api.deepseek.com/anthropic':'https://openrouter.ai/api/v1'} value={value.endpoint??''} onChange={e=>update('endpoint',e.target.value)}/></label>}
   {!external&&!attached&&value.provider!=='demo'&&<><label>密钥环境变量名称<input placeholder={value.provider==='claude'?'ANTHROPIC_API_KEY':value.provider==='deepseek'?'DEEPSEEK_API_KEY':'OPENAI_API_KEY'} value={value.credentialEnv} onChange={e=>update('credentialEnv',e.target.value)}/></label><p className="form-note">只保存变量名。请在启动服务前设置密钥；密钥不会返回浏览器。原生 Agent 使用隔离配置，不自动读取你的完整用户目录。{value.provider==='claude'?' Claude 会将该密钥以 ANTHROPIC_AUTH_TOKEN 注入，并配合上面的兼容端点使用（留空端点则走官方 Anthropic API）。':''}</p></>}
   <label className="checkbox-label"><input type="checkbox" checked={value.enabled} onChange={e=>update('enabled',e.target.checked)}/><span>允许在房间中被点名和分派任务</span></label>
    {!isNew&&!attached&&value.provider!=='demo'&&roomId&&<><div className="form-grid"><button type="button" className="button" disabled={busy} onClick={()=>void showConnect()}>生成外部 MCP 接入配置</button>{connect&&<button type="button" className="button" onClick={()=>void copyConnect()}>复制配置</button>}{connect&&<button type="button" className="button" disabled={busy} onClick={()=>void writeConnect()}>写入管理目录</button>}</div>{connect&&<textarea className="connect-config" readOnly rows={14} value={connect} onFocus={event=>event.currentTarget.select()}/>}{connect&&<div className="form-grid"><select value={installTarget} onChange={event=>setInstallTarget(event.target.value)}><option value="claude">Claude Code 用户配置</option><option value="claude-project">Claude 项目 .mcp.json</option><option value="codex">Codex config.toml</option><option value="dsh">DSH acp profile</option></select><button type="button" className="button" disabled={busy} onClick={()=>void previewInstall()}>预览变更</button><button type="button" className="button" disabled={busy} onClick={()=>void installConnector()}>安装到客户端配置</button><button type="button" className="button" disabled={busy} onClick={()=>void uninstallConnector()}>卸载</button></div>}{connect&&installTarget==='claude-project'&&<label className="form-label">项目目录<input placeholder="D:\Projects\my-project" value={projectDir} onChange={event=>setProjectDir(event.target.value)}/></label>}{previewText&&<textarea className="connect-config" readOnly rows={16} value={previewText} onFocus={event=>event.currentTarget.select()}/>}</>}
   {report&&<DiagnosticView report={report}/>}
   <div className="modal-actions"><button type="button" className="button" disabled={busy} onClick={()=>void inspect()}>保存并诊断</button>{local&&(value.executionMode??'sandbox')!=='host'&&<button type="button" className="button" disabled={busy} onClick={()=>void inspect(true)}>隔离启动检查 · 无模型请求</button>}<button className="button primary" disabled={busy}>{busy?'处理中…':'保存连接'}</button></div>
  </form>
 </Modal>;
}
function RoomForm({existing,agents,onClose,onSubmit}:{existing?:Room;agents:AgentDescriptor[];onClose:()=>void;onSubmit:(payload:any)=>Promise<void>}){
 const [name,setName]=useState(existing?.name??''),[description,setDescription]=useState(existing?.description??''),[members,setMembers]=useState(existing?.members??agents.map(a=>a.id)),[busy,setBusy]=useState(false);
 return <Modal title={existing?'房间设置':'创建一个共同工作的地方'} subtitle="围绕一个项目或话题，保留讨论和成果。" onClose={onClose}><form className="form" onSubmit={e=>{e.preventDefault();setBusy(true);void onSubmit({name,description,members}).finally(()=>setBusy(false));}}><label>房间名称<input required maxLength={80} autoFocus placeholder="例如：下一版产品" value={name} onChange={e=>setName(e.target.value)}/></label><label>一句话描述<input maxLength={300} placeholder="这个房间想共同完成什么？" value={description} onChange={e=>setDescription(e.target.value)}/></label><fieldset><legend>邀请 Agent</legend>{agents.map(agent=><label className="checkbox-label" key={agent.id}><input type="checkbox" checked={members.includes(agent.id)} onChange={e=>setMembers(m=>e.target.checked?[...m,agent.id]:m.filter(id=>id!==agent.id))}/><span>{agent.name}</span><small className="muted">{agent.enabled?'已启用':'待配置'}</small></label>)}</fieldset><div className="modal-actions"><button className="button" type="button" onClick={onClose}>取消</button><button className="button primary" disabled={busy}>{existing?'保存设置':'创建房间'}</button></div></form></Modal>;
}
function DiscussionForm({agents,onClose,onSubmit}:{agents:AgentDescriptor[];onClose:()=>void;onSubmit:(payload:any)=>Promise<void>}){
 const [goal,setGoal]=useState(''),[participants,setParticipants]=useState(agents.slice(0,3).map(a=>a.id)),[rounds,setRounds]=useState(3),[maxResponses,setMaxResponses]=useState(9),[quorum,setQuorum]=useState(0),[minutes,setMinutes]=useState(10),[busy,setBusy]=useState(false);
 return <Modal title="让不同的视角碰一碰" subtitle="设定目标和边界，成员会分轮回应彼此。" onClose={onClose}><form className="form" onSubmit={event=>{event.preventDefault();setBusy(true);void onSubmit({goal,participants,rounds,maxResponses,maxDurationMs:minutes*60000,...(quorum>0?{quorum}:{})}).finally(()=>setBusy(false));}}>
  <label>这场讨论要解决什么？<textarea required autoFocus rows={3} placeholder="例如：讨论这个功能的实现方案，并提出验收条件。" value={goal} onChange={event=>setGoal(event.target.value)}/></label>
  <fieldset><legend>参与成员（最多 20 位）</legend>{agents.map(agent=><label className="checkbox-label" key={agent.id}><input type="checkbox" checked={participants.includes(agent.id)} disabled={!participants.includes(agent.id)&&participants.length>=20} onChange={event=>setParticipants(previous=>event.target.checked?[...previous,agent.id]:previous.filter(id=>id!==agent.id))}/><Avatar agent={agent}/><span>{agent.name}</span></label>)}</fieldset>
  <div className="form-grid"><label>讨论轮次<input type="number" required min={1} max={20} value={rounds} onChange={event=>setRounds(Number(event.target.value))}/></label><label>最多响应次数<input type="number" required min={1} max={100} value={maxResponses} onChange={event=>setMaxResponses(Number(event.target.value))}/></label><label>最长时间（分钟）<input type="number" required min={1} max={120} value={minutes} onChange={event=>setMinutes(Number(event.target.value))}/></label><label>推进所需成功响应（0=全部）<input type="number" required min={0} max={20} value={quorum} onChange={event=>setQuorum(Number(event.target.value))}/></label></div>
  <p className="form-note">轮次、响应次数或时间任一达到上限即结束。每位成员每轮最多回应一次；quorum 为每轮推进所需的最少成功响应，未达 quorum 会停止，达到后未完成的成员记为缺席。真实成员的响应可能产生模型费用。</p>
  <div className="modal-actions"><button className="button" type="button" onClick={onClose}>取消</button><button className="button primary" disabled={busy||!participants.length}><Icon name="play" size={14}/>开始讨论</button></div>
 </form></Modal>;
}
function TaskForm({agents,tasks,onClose,onSubmit}:{agents:AgentDescriptor[];tasks:RoomSnapshot['tasks'];onClose:()=>void;onSubmit:(payload:any)=>Promise<void>}){
 const [title,setTitle]=useState(''),[agentId,setAgentId]=useState(agents[0]?.id??''),[projectPath,setProjectPath]=useState(''),[dependencies,setDependencies]=useState<string[]>([]),[open,setOpen]=useState(false),[busy,setBusy]=useState(false);
 return <Modal title="把下一步交给合适的成员" subtitle="工作在独立空间完成，原项目由你决定何时更新。" onClose={onClose}><form className="form" onSubmit={e=>{e.preventDefault();setBusy(true);void onSubmit({title,...(open?{open:true}:{agentId}),projectPath,dependencies}).finally(()=>setBusy(false));}}><label>任务与验收要求<textarea required rows={3} autoFocus placeholder="描述要完成的工作，以及怎样算完成。" value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="checkbox-label"><input type="checkbox" checked={open} onChange={e=>setOpen(e.target.checked)}/><span>开放认领：不指定负责人，由任一已启用成员自行领取</span></label>{!open&&<label>负责人<select value={agentId} onChange={e=>setAgentId(e.target.value)}>{agents.map(a=><option key={a.id} value={a.id}>{a.name}{a.provider==='demo'?'（演示，不执行代码）':''}</option>)}</select></label>}<label>项目绝对路径（可选）<input placeholder="D:\Projects\my-project" value={projectPath} onChange={e=>setProjectPath(e.target.value)}/></label><p className="form-note">留空时只讨论与交付报告。填写路径后建立独立快照，默认排除凭据、依赖目录和应用状态。</p>{tasks.length>0&&<fieldset><legend>等待其他任务完成（可选）</legend>{tasks.map(task=><label className="checkbox-label" key={task.id}><input type="checkbox" checked={dependencies.includes(task.id)} onChange={e=>setDependencies(d=>e.target.checked?[...d,task.id]:d.filter(id=>id!==task.id))}/><span>{task.title.slice(0,80)}</span></label>)}</fieldset>}<div className="modal-actions"><button className="button" type="button" onClick={onClose}>取消</button><button className="button primary" disabled={busy||(!open&&!agentId)}>创建任务</button></div></form></Modal>;
}
createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
